"""Informe gerencial con portada UASD, gráficos y vínculo de solución."""
from pathlib import Path
from collections import Counter
import os,tempfile
os.environ.setdefault('MPLCONFIGDIR',str(Path(tempfile.gettempdir())/'visualizacion-matplotlib'))
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from datos import ROOT,load,audit,metrics
from generar_excel import URL

G=ROOT/'graficos';G.mkdir(exist_ok=True)
BLUE='#126782';TEAL='#219EBC';GOLD='#E9A23B';PURPLE='#7B6BA8'
SOURCE='Fuente: CSV de la práctica Unidad II, UASDVirtual · Industrias Caribe S.A.'

def figures(data,m):
    plt.rcParams.update({'font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.titlesize':13,'figure.facecolor':'white'})
    def save(name):
        plt.figtext(.02,.012,SOURCE,fontsize=7,color='#4E6170');plt.tight_layout(rect=(0,.055,1,1));plt.savefig(G/f'{name}.png',dpi=170);plt.close()
    plt.figure(figsize=(9,4));items=m['categories'].most_common();plt.barh([c for c,n in items],[n for c,n in items],color=BLUE);plt.gca().invert_yaxis();plt.xlim(0,132);plt.xlabel('Reclamos (cantidad)');plt.title('Empaque concentra 110 de los 450 reclamos (24.44 %)')
    for i,(c,n) in enumerate(items):plt.text(n+1,i,f'{n} ({n/450:.1%})',va='center')
    save('01_categoria')
    plt.figure(figsize=(9,3.8));states=['Resuelto','En proceso','Abierto'];values=[m['states'][x] for x in states];plt.bar(states,values,color=[TEAL,GOLD,PURPLE]);plt.ylim(0,365);plt.ylabel('Reclamos (cantidad)');plt.title('Quedan 132 reclamos sin resolver: 78 en proceso y 54 abiertos')
    for i,n in enumerate(values):plt.text(i,n+5,str(n),ha='center')
    save('02_estado')
    plt.figure(figsize=(9,3.9));items=sorted(m['months'].items());plt.plot([d.strftime('%Y-%m') for d,n in items],[n for d,n in items],marker='o',color=BLUE);plt.xticks(rotation=45,ha='right');plt.ylim(0,55);plt.ylabel('Reclamos (cantidad)');plt.title('El registro continúa en enero de 2026 con 27 reclamos');save('03_mes_reclamo')
    plt.figure(figsize=(9,3.9));regions=sorted({x['Region'] for x in data['Reclamos']});left=np.zeros(len(regions))
    for pri,col in [('Alta',GOLD),('Media',BLUE),('Baja',PURPLE)]:
        counts=[sum(x['Region']==r and x['Prioridad']==pri for x in data['Reclamos']) for r in regions];plt.barh(regions,counts,left=left,label=pri,color=col);left+=counts
    plt.xlabel('Reclamos (cantidad)');plt.xlim(0,145);plt.title('La carga de atención varía por región y prioridad');plt.legend(title='Prioridad',ncols=3,loc='lower right');save('04_region_prioridad')
    plants=list(m['plants']);values=list(m['plants'].values());x=np.arange(len(plants));plt.figure(figsize=(9,4));plt.bar(x-.18,[v[0] for v in values],.36,label='Planificadas',color=PURPLE);plt.bar(x+.18,[v[1] for v in values],.36,label='Producidas',color=BLUE);plt.xticks(x,[p.replace('Planta ','') for p in plants]);plt.ylabel('Unidades');plt.ylim(0,620000);plt.ticklabel_format(axis='y',style='plain');plt.title('Ambas plantas producen por debajo del plan agregado');plt.legend();save('05_plan_planta')
    products=sorted(m['products'],key=lambda x:-m['products'][x][2]/m['products'][x][1]);rates=[100*m['products'][p][2]/m['products'][p][1] for p in products];plt.figure(figsize=(9,4));plt.barh(products,rates,color=GOLD);plt.gca().invert_yaxis();plt.xlim(0,4.2);plt.xlabel('Unidades defectuosas / producidas (%)');plt.title('Galletas Avena tiene la mayor tasa observada: 3.53 %')
    for i,v in enumerate(rates):plt.text(v+.03,i,f'{v:.2f} %',va='center')
    save('06_defectos_producto')
    items=list(m['production_months'].items());plt.figure(figsize=(9,3.9));plt.plot([d.strftime('%Y-%m') for d,v in items],[v[1] for d,v in items],marker='o',color=BLUE);plt.xticks(rotation=45,ha='right');plt.ylim(0,max(v[1] for d,v in items)*1.2);plt.ylabel('Unidades producidas');plt.title('La producción mensual fluctúa durante 2025');save('07_produccion_mes')
    plt.figure(figsize=(9,3.9));shifts=list(m['shifts']);v=list(m['shifts'].values());x=np.arange(len(shifts));plt.bar(x-.18,[a[0] for a in v],.36,label='Planificadas',color=PURPLE);plt.bar(x+.18,[a[1] for a in v],.36,label='Producidas',color=TEAL);plt.xticks(x,shifts);plt.ylim(0,450000);plt.ylabel('Unidades');plt.title('Tarde registra el mayor volumen: 372,409 unidades');plt.legend();save('08_turno')

def build():
    data=load();checks=audit(data);m=metrics(data);figures(data,m);plan,produced,defects=m['totals']
    fonts=Path(matplotlib.get_data_path())/'fonts/ttf'
    for name,filename in [('Body','DejaVuSans.ttf'),('Body-Bold','DejaVuSans-Bold.ttf'),('Body-Italic','DejaVuSans-Oblique.ttf')]:pdfmetrics.registerFont(TTFont(name,str(fonts/filename)))
    pdfmetrics.registerFontFamily('Body',normal='Body',bold='Body-Bold',italic='Body-Italic',boldItalic='Body-Bold')
    styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='ES',fontName='Body',fontSize=10,leading=14,spaceAfter=7));styles.add(ParagraphStyle(name='Cell',fontName='Body',fontSize=9,leading=12,spaceAfter=2));styles.add(ParagraphStyle(name='Cover',fontName='Body',fontSize=13,leading=21,alignment=1,spaceAfter=14));styles.add(ParagraphStyle(name='H',fontName='Body-Bold',fontSize=13,leading=17,spaceBefore=12,spaceAfter=8,keepWithNext=True,textColor=colors.HexColor(BLUE)))
    story=[]
    class WholeParagraph(Paragraph):
        def split(self,availWidth,availHeight):return []
    def p(t):story.append(WholeParagraph(t,styles['ES']))
    def h(t):story.append(Paragraph(t,styles['H']))
    def table(rows,widths):
        t=Table([[Paragraph(str(c),styles['Cell']) for c in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#E6F1F5')),('GRID',(0,0),(-1,-1),.3,colors.HexColor('#D1DDE3')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story.append(t);story.append(Spacer(1,7))
    def image(name):
        from PIL import Image as PI
        with PI.open(G/f'{name}.png') as im:ratio=im.height/im.width
        story.append(Image(str(G/f'{name}.png'),width=455,height=455*ratio))
    def keep(start):
        a=story[start:];del story[start:];story.append(KeepTogether(a))
    def cv(t):story.append(Paragraph(t,styles['Cover']))
    logo=ROOT.parents[1]/'Unidad I/Practica 1/recursos/uasd_logo.png';story.append(Spacer(1,15));story.append(Image(str(logo),width=105,height=125,kind='proportional'));story.append(Spacer(1,16));cv('<b>UNIVERSIDAD AUTÓNOMA DE SANTO DOMINGO</b>');cv('UASD · Primada de América');story.append(Spacer(1,20));cv('<b>Visualización de Datos I</b><br/>INF-8240-C2');cv('<b>Práctica Unidad II</b><br/>Creación y análisis de gráficas<br/>Industrias Caribe S.A.');story.append(Spacer(1,20));cv('<b>Presentado por</b><br/>Marlenis Judith Concepción Cuevas');story.append(Spacer(1,25));cv('Santo Domingo, República Dominicana<br/>2 de noviembre de 2026');story.append(PageBreak())
    h('Informe gerencial · Industrias Caribe S.A.');p('Objetivo: describir la carga de reclamos y el desempeño productivo, construir dos dashboards revisables y proponer acciones sustentadas en los datos de la consigna.')
    h('Resumen ejecutivo');table([['Reclamos','Resultado','Producción','Resultado'],['Total','450','Planificadas',f'{plan:,} unidades'],['Resueltos','318 (70.67 %)','Producidas',f'{produced:,} unidades'],['Pendientes','132 (29.33 %)','Defectuosas',f'{defects:,} unidades'],['Días promedio','8.94 días (n = 318)','Tasa de defectos',f'{defects/produced:.2%}'],['Satisfacción','3.08 / 5 (n = 318)','Cumplimiento',f'{produced/plan:.2%}']],[105,125,115,125]);p('Empaque reúne 110 reclamos (24.44 %). Se recomienda revisar el empaque y priorizar pendientes según riesgo y antigüedad. Producción presenta una brecha de 57,107 unidades frente al plan; se recomienda investigar las brechas por planta y los defectos de los productos con mayores tasas. Las comparaciones son descriptivas, sin atribución causal.')
    h('Preparación y validación de los datos');p('Se importaron los tres CSV originales: Reclamos (450 filas), Produccion (1,200) y Ventas (3,000). La copia de Ventas es idéntica y no se sumó. Se conservaron los encabezados, se tiparon conteos e importes y se convirtieron las fechas ISO a fechas reales de Excel. Se crearon tblReclamos y tblProduccion, además de tblVentas para verificar las relaciones.');p('ReclamoID, LoteID y VentaID son únicos en sus respectivas tablas. Todos los VentaID de reclamos existen en ventas; producto y región coinciden con su venta asociada y no hay reclamos anteriores a su venta. Producción no tiene campos vacíos; las unidades son positivas y las defectuosas no superan a las producidas. Los controles detallados están en la hoja Validacion.');p('Se preservaron 132 vacíos en DiasResolucion y otros 132 en Satisfaccion_1a5. Corresponden a los 78 casos En proceso y 54 Abierto. Los 318 resueltos tienen ambos datos. Satisfacción se encuentra entre 1 y 5 y no hay días negativos. No se reemplazaron vacíos por cero.')
    h('Parte A · Reclamos');h('Procedimiento y fórmulas revisables');p('MesReclamo = FECHA(AÑO([@FechaReclamo]); MES([@FechaReclamo]); 1). Esta columna conserva año y mes; evita agrupar enero de 2025 con enero de 2026. El registro de reclamos abarca del 2 de enero de 2025 al 28 de enero de 2026, mientras las ventas corresponden a 2025.');table([['Indicador','Fórmula en Excel (español)','Resultado'],['Total','=CONTARA(tblReclamos[ReclamoID])','450'],['Resueltos','=CONTAR.SI(tblReclamos[Estado];"Resuelto")','318'],['Tasa resuelta','=318/450','70.67 %'],['Días promedio','=PROMEDIO(tblReclamos[DiasResolucion])','2,842 / 318 = 8.94'],['Satisfacción','=PROMEDIO(tblReclamos[Satisfaccion_1a5])','979 / 318 = 3.08']],[85,290,95]);p('Las fórmulas internas del archivo XLSX se guardan en el estándar de Excel y se muestran traducidas según la instalación. PROMEDIO omite vacíos: los días representan únicamente los casos con resolución registrada y la satisfacción solo las respuestas disponibles. Incluir ceros reduciría indebidamente ambos promedios; además, una satisfacción cero estaría fuera de la escala 1–5.')
    start=len(story);h('Empaque es la categoría con más reclamos');image('01_categoria');table([['Categoría','Casos','Participación']]+[[c,n,f'{n/450:.2%}'] for c,n in m['categories'].most_common()],[235,100,135]);p('Hallazgo 1: Empaque concentra 110 de 450 casos, seguido de Atención con 92. La barra horizontal permite comparar conteos desde cero y leer categorías largas. Es composición del conjunto de reclamos, no una tasa por producto ni una prueba de peor calidad relativa.');keep(start)
    start=len(story);h('El 29.33 % de los casos sigue sin resolver');image('02_estado');p('Hallazgo 2: hay 318 Resuelto, 78 En proceso y 54 Abierto. Si «abiertos» significa el estado literal, son 54; si significa pendientes de resolución, son 132. La tasa resuelta es 318 / 450 = 70.67 %. Las columnas comparan categorías, sin suponer que los estados son intervalos temporales.');keep(start)
    start=len(story);h('La serie de reclamos incluye enero de 2026');image('03_mes_reclamo');p('Hallazgo 3: enero de 2026 aporta 27 casos (6.00 % del total). Septiembre de 2025 registra el mayor conteo mensual, 47, frente a 15 en enero de 2025. La línea conserva el orden año-mes. Un mes con más casos no implica mayor tasa: faltan exposición y cohortes temporales compatibles para esa comparación.');keep(start)
    start=len(story);h('Prioridad y región orientan el análisis de la carga');image('04_region_prioridad');p('Las barras apiladas combinan volumen regional y composición por prioridad. Los segmentos interiores se comparan con menor precisión que una barra desde cero; por eso el Excel conserva la tabla cruzada TD_RegionPrioridad con sus totales. Esta vista sirve para identificar dónde revisar la carga, sin concluir que una región causa los problemas.');keep(start)
    h('Dos recomendaciones y una limitación · Reclamos');p('<b>1. Revisar el empaque.</b> Responsable propuesto: Calidad y Logística. Auditar una muestra de recepción, almacenamiento y despacho y clasificar los 110 casos de Empaque por motivo y producto. Indicador de seguimiento: recurrencia por motivo; cuando exista un denominador compatible, reclamos por unidades o pedidos expuestos. El volumen justifica investigar, no atribuir una causa.');p('<b>2. Gestionar los pendientes por riesgo y antigüedad.</b> Responsable propuesto: Servicio al Cliente. Revisar los 132 pendientes, separar prioridad Alta y calcular su antigüedad con una fecha de corte explícita. Monitorear entradas, cierres y casos vencidos por semana; fijar metas después de conocer capacidad y compromisos de servicio.');p('<b>Limitación:</b> los promedios de 8.94 días y 3.08/5 describen los 318 casos con datos; no representan el tiempo final ni la satisfacción de los 132 aún sin registro. El 70.67 % es una proporción de estados observados, no una tasa de cierre por cohorte o un indicador de cumplimiento de SLA.')
    h('Parte B · Producción');h('Indicadores y procedimiento');table([['Indicador','Cálculo: razón de sumas','Resultado'],['Planificadas','SUMA(UnidadesPlanificadas)',f'{plan:,}'],['Producidas','SUMA(UnidadesProducidas)',f'{produced:,}'],['Defectuosas','SUMA(UnidadesDefectuosas)',f'{defects:,}'],['Tasa de defectos',f'{defects:,} / {produced:,}',f'{defects/produced:.4%}'],['Cumplimiento',f'{produced:,} / {plan:,}',f'{produced/plan:.4%}']],[105,255,110]);p('La tasa global de defectos es 3.4285 %. El promedio simple de las tasas de lotes sería 3.4049 % y daría el mismo peso a lotes de distinto tamaño. Se usa razón de sumas para ponderar por unidades producidas. No se equiparan unidades defectuosas con desperdicio monetario; CostoProduccion_DOP no establece por sí solo cuánto cuesta cada defecto o si puede reprocesarse.')
    start=len(story);h('Ambas plantas quedan por debajo del plan agregado');image('05_plan_planta');table([['Planta','Planificadas','Producidas','Cumplimiento']]+[[k.replace('Planta ',''),f'{v[0]:,}',f'{v[1]:,}',f'{v[1]/v[0]:.2%}'] for k,v in m['plants'].items()],[145,110,110,105]);p('Hallazgo 1: se producen 1,024,428 de 1,081,535 unidades planificadas: 94.72 % de cumplimiento y brecha de 57,107 unidades (5.28 %). Las columnas agrupadas usan la misma escala y comparan plan y real por planta.');keep(start)
    start=len(story);h('Galletas Avena presenta la mayor tasa observada');image('06_defectos_producto');table([['Producto','Producidas','Defectuosas','Tasa']]+[[k,f'{v[1]:,}',f'{v[2]:,}',f'{v[2]/v[1]:.2%}'] for k,v in sorted(m['products'].items(),key=lambda kv:-kv[1][2]/kv[1][1])],[185,100,100,85]);p('Hallazgo 2: Galletas Avena registra 6,768 / 191,971 = 3.53 %, frente a 3.32 % en Jugo Mango, una diferencia de 0.21 puntos porcentuales. Refresco Cola se sitúa en 3.52 %. Las barras comparan razones de sumas por producto; la diferencia observada no demuestra una causa ni significación estadística.');keep(start)
    start=len(story);h('Los agregados ocultan lotes que superan el plan');image('07_produccion_mes');p('La línea mensual permite revisar cuándo se concentran variaciones. Hallazgo 3: 419 de 1,200 lotes (34.92 %) superan 100 % de cumplimiento individual, aunque el total sea 94.72 %. No se eliminaron ni truncaron estos valores: representan sobrecumplimiento del plan registrado y requieren contexto sobre ajustes, capacidad o planificación.');keep(start)
    start=len(story);h('El turno Tarde concentra el mayor volumen');image('08_turno');table([['Turno','Planificadas','Producidas','Cumplimiento']]+[[k,f'{v[0]:,}',f'{v[1]:,}',f'{v[1]/v[0]:.2%}'] for k,v in m['shifts'].items()],[140,110,115,105]);p('Tarde produce 372,409 unidades, pero también tiene el mayor plan. Su volumen no demuestra mayor productividad: faltan horas trabajadas, personal, capacidad y mezcla de productos.');keep(start)
    h('Dos recomendaciones y una limitación · Producción');p('<b>1. Revisar las brechas del plan.</b> Responsable propuesto: Planificación y Producción. Desagregar la brecha de 57,107 unidades por planta, producto y mes; contrastar con paradas, horas y cambios de plan. Revisar también los 419 lotes que superan 100 % antes de redefinir metas. Seguimiento: cumplimiento ponderado y brecha en unidades, sin truncar sobrecumplimientos.');p('<b>2. Investigar los defectos en productos prioritarios.</b> Responsable propuesto: Calidad. Empezar con Galletas Avena y Refresco Cola por sus tasas observadas y revisar tipo de defecto, lote, turno y condiciones del proceso. Seguimiento: defectuosas / producidas por producto y periodo, manteniendo el denominador y la mezcla comparables.');p('<b>Limitación:</b> sumar unidades de productos distintos no pondera tamaño, complejidad ni costo. Sin horas, capacidad, severidad o valoración de defectos, no puede medirse productividad laboral ni desperdicio monetario, ni atribuir las diferencias a una planta o turno.')
    h('Dashboards, filtros y verificación de la solución');p('El libro contiene 10 tablas dinámicas nativas y dos cachés compartidas. Dashboard_Reclamos incluye los cuatro KPI solicitados y cuatro gráficos; sus segmentadores Region, Categoria y Estado se conectan a las cinco TD de reclamos. Dashboard_Produccion contiene seis KPI y cuatro gráficos, con Planta, Turno y Producto conectados a las cinco TD de producción.');p('Los KPI y las series de los gráficos usan GETPIVOTDATA sobre sus TD. No dependen de totales globales que ignoren el filtro. Los resúmenes globales permanecen identificados como tales. Conservar los filtros vacíos debe mostrar 450 y 318 en reclamos, y 1,081,535 / 1,024,428 / 35,123 en producción. Al elegir Estado = Resuelto, total y resueltos deben mostrar 318; Estado = Abierto debe mostrar total 54 y resueltos 0, con promedios sin datos. Al elegir Planta Santiago, plan = 545,792, real = 516,231 y defectuosas = 17,354.');p('Se verificaron importación, integridad del archivo, controles docentes, conciliación de resúmenes, diez definiciones de TD y conexiones de seis segmentadores. La ejecución visual de los segmentadores requiere Excel compatible; no se ha comprobado su interacción en Excel de escritorio en este entorno. Los valores iniciales están guardados y el informe presenta la vista global.');
    h('GitHub · Solución y archivos utilizados');p(f'<link href="{URL}" color="{BLUE}"><u>Abrir la solución de Unidad II · Industrias Caribe S.A.</u></link>');p('Repositorio: github.com/marlenis-concepcion/CienciaDatosUasd2026<br/>Carpeta: Visualización de Datos I / INF-8240-C2 / Unidad II / Practica 2');h('Fuentes');p('UASDVirtual. (s. f.). <i>Práctica Unidad II: Creación y análisis de gráficas Industrias Caribe S.A.</i> [Consigna y archivos CSV, INF-8240-C2]. Material facilitado por la estudiante.');p('Datos originales: IndustriasCaribe_Reclamos.csv, IndustriasCaribe_Produccion.csv e IndustriasCaribe_Ventas.csv. Cálculos y gráficos de elaboración propia con apoyo de herramientas de programación e IA; deben revisarse antes de entregar. Escudo UASD: recurso ya documentado en el repositorio (Wikimedia Commons, CC BY-SA 4.0).')
    def footer(canvas,doc):
        if doc.page==1:return
        canvas.setFont('Body',7);canvas.drawString(45,23,'INF-8240-C2 · Unidad II · Marlenis Judith Concepción Cuevas');canvas.drawRightString(553,23,str(doc.page-1))
    SimpleDocTemplate(str(ROOT/'Informe_Unidad_II_IndustriasCaribe.pdf'),leftMargin=45,rightMargin=45,topMargin=35,bottomMargin=42).build(story,onFirstPage=footer,onLaterPages=footer)
    print('Informe PDF con portada UASD, ocho gráficos y enlace de GitHub generado.')

if __name__=='__main__':build()
